def matrix_evolution(items) -> dict:
    """Track per-model :func:`converge_matrix` evolution across periods.

    ``items`` must be a list of at least two mappings, each with exactly
    the keys ``period, models`` in that order.  ``period`` is a non-empty
    str that is unique across items and ``models`` is a non-empty mapping
    of non-empty str model names to complete :func:`converge_matrix`
    results (schema ``climate-grid/cvm-v1``); every matrix is validated
    against that contract.  All items must share the same model key
    order and all matrices must share the same ``tolerance``, the same
    ``layers`` and the same scenario order, taken from the first item's
    first model.

    For every adjacent pair of periods (in item order), every model (in
    the shared model order) and every scenario (in the shared scenario
    order) the row ``from`` and ``to`` are the earlier and later
    ``state``.  When both rows have an ``interval``, ``interval`` is
    ``[later lo − earlier lo, later hi − earlier hi]``; otherwise it is
    ``None``.  ``rank`` is the later ``rank`` minus the earlier ``rank``
    when both are present, else ``None``.

    The returned mapping uses the key order ``schema, periods, models,
    scenarios, data``; ``schema`` is ``climate-grid/cme-v1``,
    ``periods`` lists the item periods in order, ``models`` the shared
    model order and ``scenarios`` the shared scenario order.  ``data``
    iterates the adjacent period pairs in order, then the models, then
    the scenarios; each row uses the key order ``left, right, model,
    scenario, from, to, interval, rank`` where ``left`` and ``right``
    are the earlier and later period.  ``rank`` is an int and every
    output float is ``round(x, 12)`` with negative zero normalized to
    ``0.0``.  The input is not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 2:
        raise ValueError("items must contain at least 2 items")

    periods = []
    validated: list[dict] = []
    seen_periods: set[str] = set()
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _MATRIX_EVOLUTION_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys period, models in "
                "order"
            )

        period = item["period"]
        if not isinstance(period, str):
            raise TypeError(f"{where}.period must be a str")
        if period == "":
            raise ValueError(f"{where}.period must be non-empty")
        if period in seen_periods:
            raise ValueError(f"duplicate items period: {period!r}")
        seen_periods.add(period)

        models = item["models"]
        if not isinstance(models, dict):
            raise TypeError(f"{where}.models must be a dict")
        if len(models) == 0:
            raise ValueError(f"{where}.models must be non-empty")

        lookups = {}
        for model, matrix in models.items():
            if not isinstance(model, str):
                raise TypeError(f"{where}.models keys must be str")
            if model == "":
                raise ValueError(f"{where}.models keys must be non-empty")
            tolerance, layers, data = _validate_converge_matrix(
                matrix, where=f"{where}.models[{model!r}]"
            )
            scenarios = [row["scenario"] for row in data]
            if not validated and not lookups:
                first_tolerance = tolerance
                first_layers = layers
                first_scenarios = scenarios
            else:
                if tolerance != first_tolerance:
                    raise ValueError(
                        "all matrices must share the same tolerance, "
                        "taken from the first item"
                    )
                if layers != first_layers:
                    raise ValueError(
                        "all matrices must share the same layers, "
                        "taken from the first item"
                    )
                if scenarios != first_scenarios:
                    raise ValueError(
                        "all matrices must share the same scenario "
                        "order, taken from the first item"
                    )
            lookups[model] = {row["scenario"]: row for row in data}

        if not validated:
            first_models = list(models.keys())
        elif list(models.keys()) != first_models:
            raise ValueError(
                "all items must share the same model order, taken from "
                "the first item"
            )

        periods.append(period)
        validated.append(lookups)

    rows = []
    for left_index in range(len(items) - 1):
        earlier = validated[left_index]
        later = validated[left_index + 1]
        for model in first_models:
            for scenario in first_scenarios:
                before = earlier[model][scenario]
                after = later[model][scenario]
                if (
                    before["interval"] is not None
                    and after["interval"] is not None
                ):
                    interval = [
                        _round_output(
                            after["interval"][0] - before["interval"][0]
                        ),
                        _round_output(
                            after["interval"][1] - before["interval"][1]
                        ),
                    ]
                else:
                    interval = None
                if before["rank"] is not None and after["rank"] is not None:
                    rank = after["rank"] - before["rank"]
                else:
                    rank = None
                rows.append(
                    {
                        "left": periods[left_index],
                        "right": periods[left_index + 1],
                        "model": model,
                        "scenario": scenario,
                        "from": before["state"],
                        "to": after["state"],
                        "interval": interval,
                        "rank": rank,
                    }
                )

    return {
        "schema": _MATRIX_EVOLUTION_SCHEMA,
        "periods": periods,
        "models": list(first_models),
        "scenarios": list(first_scenarios),
        "data": rows,
    }


_MATRIX_EVOLUTION_OUTPUT_KEYS = (
    "schema",
    "periods",
    "models",
    "scenarios",
    "data",
)
_MATRIX_EVOLUTION_ROW_KEYS = (
    "left",
    "right",
    "model",
    "scenario",
    "from",
    "to",
    "interval",
    "rank",
)
_MATRIX_EVOLUTION_SUMMARY_SCHEMA = "climate-grid/cme-summary-v1"
_MATRIX_EVOLUTION_SUMMARY_KEYS = (
    "schema",
    "periods",
    "models",
    "scenarios",
    "data",
)
_MATRIX_EVOLUTION_SUMMARY_ROW_KEYS = (
    "model",
    "scenario",
    "total",
    "count",
    "transitions",
    "interval",
    "rank_mean",
    "rank_abs",
)


def _validate_matrix_evolution(result: Any, *, where: str = "result") -> tuple:
    """Validate a complete :func:`matrix_evolution` result.

    Returns the ``periods``, ``models`` and ``scenarios`` axes and the
    ``data`` rows.  Rows must follow the flat adjacent-pair-then-model-
    then-scenario order of the ``climate-grid/cme-v1`` contract.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _MATRIX_EVOLUTION_OUTPUT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, periods, models, "
            "scenarios, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _MATRIX_EVOLUTION_SCHEMA:
        raise ValueError(f"{where}.schema must be {_MATRIX_EVOLUTION_SCHEMA!r}")

    periods = result["periods"]
    if not isinstance(periods, list):
        raise TypeError(f"{where}.periods must be a list")
    if len(periods) < 2:
        raise ValueError(f"{where}.periods must contain at least 2 entries")
    seen_periods: set[str] = set()
    for index, period in enumerate(periods):
        if not isinstance(period, str):
            raise TypeError(f"{where}.periods[{index}] must be a str")
        if period == "":
            raise ValueError(f"{where}.periods[{index}] must be non-empty")
        if period in seen_periods:
            raise ValueError(f"duplicate {where}.periods entry: {period!r}")
        seen_periods.add(period)

    models = result["models"]
    if not isinstance(models, list):
        raise TypeError(f"{where}.models must be a list")
    if len(models) == 0:
        raise ValueError(f"{where}.models must be non-empty")
    seen_models: set[str] = set()
    for index, model in enumerate(models):
        if not isinstance(model, str):
            raise TypeError(f"{where}.models[{index}] must be a str")
        if model == "":
            raise ValueError(f"{where}.models[{index}] must be non-empty")
        if model in seen_models:
            raise ValueError(f"duplicate {where}.models entry: {model!r}")
        seen_models.add(model)

    scenarios = result["scenarios"]
    if not isinstance(scenarios, list):
        raise TypeError(f"{where}.scenarios must be a list")
    if len(scenarios) == 0:
        raise ValueError(f"{where}.scenarios must be non-empty")
    seen_scenarios: set[str] = set()
    for index, scenario in enumerate(scenarios):
        if not isinstance(scenario, str):
            raise TypeError(f"{where}.scenarios[{index}] must be a str")
        if scenario == "":
            raise ValueError(f"{where}.scenarios[{index}] must be non-empty")
        if scenario in seen_scenarios:
            raise ValueError(f"duplicate {where}.scenarios entry: {scenario!r}")
        seen_scenarios.add(scenario)

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    n_pairs = len(periods) - 1
    n_models = len(models)
    n_scenarios = len(scenarios)
    expected_rows = n_pairs * n_models * n_scenarios
    if len(data) != expected_rows:
        raise ValueError(
            f"{where}.data must have {expected_rows} rows (one per adjacent "
            "period pair/model/scenario combination, in pair-then-model-then-"
            "scenario order)"
        )

    row_index = 0
    for pair_index in range(n_pairs):
        for model in models:
            for scenario in scenarios:
                row_where = f"{where}.data[{row_index}]"
                row = data[row_index]
                if not isinstance(row, dict):
                    raise TypeError(f"{row_where} must be a dict")
                if tuple(row.keys()) != _MATRIX_EVOLUTION_ROW_KEYS:
                    raise ValueError(
                        f"{row_where} must have exactly the keys left, right, "
                        "model, scenario, from, to, interval, rank in order"
                    )

                if not isinstance(row["left"], str):
                    raise TypeError(f"{row_where}.left must be a str")
                if row["left"] != periods[pair_index]:
                    raise ValueError(
                        f"{row_where}.left must be {periods[pair_index]!r} "
                        "for its pair-then-model-then-scenario position"
                    )
                if not isinstance(row["right"], str):
                    raise TypeError(f"{row_where}.right must be a str")
                if row["right"] != periods[pair_index + 1]:
                    raise ValueError(
                        f"{row_where}.right must be "
                        f"{periods[pair_index + 1]!r} for its "
                        "pair-then-model-then-scenario position"
                    )
                if not isinstance(row["model"], str):
                    raise TypeError(f"{row_where}.model must be a str")
                if row["model"] != model:
                    raise ValueError(
                        f"{row_where}.model must be {model!r} for its "
                        "pair-then-model-then-scenario position"
                    )
                if not isinstance(row["scenario"], str):
                    raise TypeError(f"{row_where}.scenario must be a str")
                if row["scenario"] != scenario:
                    raise ValueError(
                        f"{row_where}.scenario must be {scenario!r} for its "
                        "pair-then-model-then-scenario position"
                    )

                for end_name in ("from", "to"):
                    end = row[end_name]
                    if end is not None and not isinstance(end, str):
                        raise TypeError(
                            f"{row_where}.{end_name} must be a str or None"
                        )
                    if end is not None and end not in _CONVERGE_STATES:
                        raise ValueError(
                            f"{row_where}.{end_name} must be one of stable, "
                            "uncertain, divergent or None"

                            "uncertain, divergent or None"
                        )

                interval = row["interval"]
                if interval is not None:
                    if not isinstance(interval, list):
                        raise TypeError(f"{row_where}.interval must be a list")
                    if len(interval) != 2:
                        raise ValueError(
                            f"{row_where}.interval must have exactly 2 bounds"
                        )
                    for bound_index, bound in enumerate(interval):
                        _validate_number(
                            bound,
                            f"{row_where}.interval[{bound_index}]",
                            nullable=False,
                        )

                rank = row["rank"]
                if rank is not None and (
                    not isinstance(rank, int) or isinstance(rank, bool)
                ):
                    raise TypeError(
                        f"{row_where}.rank must be a non-bool int or None"
                    )

                ends_present = (
                    row["from"] is not None and row["to"] is not None
                )
                if interval is not None and not ends_present:
                    raise ValueError(
                        f"{row_where}.interval must be None when either "
                        f"{row_where}.from or {row_where}.to is None"
                    )
                if ends_present and interval is None:
                    raise ValueError(
                        f"{row_where}.interval must be present when "
                        f"{row_where}.from and {row_where}.to are"
                    )
                if rank is not None and not ends_present:
                    raise ValueError(
                        f"{row_where}.rank must be None when either "
                        f"{row_where}.from or {row_where}.to is None"
                    )
                if ends_present and rank is None:
                    raise ValueError(
                        f"{row_where}.rank must be present when "
                        f"{row_where}.from and {row_where}.to are"
                    )

                row_index += 1

    return periods, models, scenarios, data


